import { expect, test, type Route } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

// A married tester's real report shape (Yoni 0/4, Gana 1/6, both Manglik,
// 6 of 6 South Indian checks), with the server's couple guidance generated by
// astrospace/core/vedic/compatibility_guidance.py.
const payload = JSON.parse(readFileSync(join(__dirname, 'fixtures', 'compat-married.json'), 'utf8'));

const profiles = [
  { id: 'profile-1', name: 'Kamalesh', relation: 'self', birth_city: 'Hyderabad', birth_nation: 'IN' },
  { id: 'profile-2', name: 'Sai Madhuri', relation: 'spouse', birth_city: 'Vijayawada', birth_nation: 'IN' },
];

test('compatibility detail leads with plain guidance for a married couple', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'mobile-chrome-360', 'One phone project covers this screen');
  await page.setViewportSize({ width: 375, height: 812 });
  await page.route('**/api/v1/**', async (route: Route) => {
    const url = new URL(route.request().url());
    if (url.pathname === '/api/v1/auth/config') return route.fulfill({ json: { enabled: false } });
    if (url.pathname === '/api/v1/kundlis') return route.fulfill({ json: profiles });
    if (url.pathname === '/api/v1/vedic/profile-1/compatibility/profile-2') return route.fulfill({ json: payload });
    return route.fulfill({ status: 503, json: { detail: `Unmocked ${url.pathname}` } });
  });

  await page.goto('/m/compat/results/detail?partner=profile-2');

  // A saved spouse starts on "Already married", with no pass/fail verdict.
  await expect(page.getByRole('radio', { name: 'Already married' })).toHaveAttribute('aria-checked', 'true');
  await expect(page.getByText('this score is not a pass or a fail')).toBeVisible();
  await expect(page.getByText('Promising match', { exact: true })).toHaveCount(0);

  await expect(page.getByText('WHERE A LITTLE CARE HELPS', { exact: true })).toBeVisible();
  await expect(page.getByRole('heading', { name: 'Closeness and affection' })).toBeVisible();
  await expect(page.getByRole('heading', { name: 'How you each react' })).toBeVisible();
  await expect(page.getByText('FOR EACH OF YOU', { exact: true })).toBeVisible();
  await expect(page.getByText('Say Om Angarakaya Namah 11 times on Tuesdays.')).toBeVisible();

  // Terms wait under the fold.
  await expect(page.getByText('EIGHT KOOTAS BREAKDOWN', { exact: true })).toBeHidden();
  await page.screenshot({ path: testInfo.outputPath('compat-married-1.png') });
  await page.getByText('WHERE A LITTLE CARE HELPS', { exact: true }).evaluate((el) => el.scrollIntoView());
  await page.screenshot({ path: testInfo.outputPath('compat-married-2.png') });
  await page.getByText('FOR EACH OF YOU', { exact: true }).evaluate((el) => el.scrollIntoView());
  await page.screenshot({ path: testInfo.outputPath('compat-married-3.png') });

  await page.getByText('Why this? The full astrology behind the score').click();
  await expect(page.getByText('EIGHT KOOTAS BREAKDOWN', { exact: true })).toBeVisible();
  // Full scores read as full, whatever the traditions' bookkeeping says.
  await expect(page.locator('.mcod-koota-row', { hasText: 'Bhakoot' }).locator('.mcod-koota-status')).toHaveText('✓');
  await expect(page.locator('.mcod-koota-row', { hasText: 'Rajju' }).locator('.mcod-koota-status')).toHaveText('✓');
  await expect(page.locator('.mcod-koota-row', { hasText: 'Yoni' }).locator('.mcod-koota-status')).toHaveText('LOW');
  await expect(page.getByText('PARTIAL', { exact: true })).toHaveCount(3); // Vashya 1/2, Tara 1.5/3, Gana 1/6
  await expect(page.getByText('Balanced', { exact: true })).toBeVisible();
  await expect(page.getByText("the first person outside marriage matching")).toHaveCount(0);
  await page.getByText('EIGHT KOOTAS BREAKDOWN', { exact: true }).evaluate((el) => el.scrollIntoView());
  await page.screenshot({ path: testInfo.outputPath('compat-married-4.png') });
  await page.getByText('SAFETY CHECKS', { exact: true }).evaluate((el) => el.scrollIntoView());
  await page.screenshot({ path: testInfo.outputPath('compat-married-5.png') });

  await page.getByRole('radio', { name: 'Planning to marry' }).click();
  await expect(page.getByText('Promising match', { exact: true })).toBeVisible();
  await expect(page.getByText('WHAT TO TALK ABOUT FIRST', { exact: true })).toBeVisible();
});

test('compatibility detail guidance reads in the dark theme', async ({ page }, testInfo) => {
  test.skip(testInfo.project.name !== 'mobile-chrome-360', 'One phone project covers this screen');
  await page.setViewportSize({ width: 375, height: 812 });
  await page.emulateMedia({ colorScheme: 'dark' });
  await page.route('**/api/v1/**', async (route: Route) => {
    const url = new URL(route.request().url());
    if (url.pathname === '/api/v1/auth/config') return route.fulfill({ json: { enabled: false } });
    if (url.pathname === '/api/v1/kundlis') return route.fulfill({ json: profiles });
    if (url.pathname === '/api/v1/vedic/profile-1/compatibility/profile-2') return route.fulfill({ json: payload });
    return route.fulfill({ status: 503, json: { detail: `Unmocked ${url.pathname}` } });
  });
  await page.goto('/m/compat/results/detail?partner=profile-2');
  await expect(page.getByRole('heading', { name: 'Closeness and affection' })).toBeVisible();
  await page.screenshot({ path: testInfo.outputPath('compat-dark-1.png') });
  await page.getByRole('heading', { name: 'Closeness and affection' }).evaluate((el) => el.scrollIntoView());
  await page.screenshot({ path: testInfo.outputPath('compat-dark-2.png') });
});
